"""Aggregate readiness scores and inter-coder agreement.

Input: codings.csv with columns developer,coder,item_id,score,source_url,quote
Usage: python score.py codings.csv
"""
import csv
import sys
from collections import defaultdict


def load(path):
    with open(path, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def main(path):
    rows = load(path)
    missing = [r for r in rows if r["score"] not in {"0", "1", "2"} or not r["source_url"].strip()]
    if missing:
        print(f"WARNING: {len(missing)} rows lack a valid score (0-2) or a source URL")

    by_key = defaultdict(dict)  # (developer, item) -> {coder: score}
    for r in rows:
        if r["score"] in {"0", "1", "2"}:
            by_key[(r["developer"], r["item_id"])][r["coder"]] = int(r["score"])

    # Agreement over items coded by exactly two or more coders
    pairs = [v for v in by_key.values() if len(v) >= 2]
    if pairs:
        agree = sum(1 for v in pairs if len(set(v.values())) == 1)
        print(f"Exact agreement: {agree}/{len(pairs)} = {agree / len(pairs):.0%}")

    # Mean score per developer (averaging coders), as % of max
    totals = defaultdict(list)
    for (dev, _item), coders in by_key.items():
        totals[dev].append(sum(coders.values()) / len(coders))
    print("\nReadiness (% of max possible, public evidence only):")
    for dev, scores in sorted(totals.items(), key=lambda kv: -sum(kv[1]) / len(kv[1])):
        pct = sum(scores) / (2 * len(scores))
        print(f"  {dev:30s} {pct:5.0%}  ({len(scores)} items)")


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "codings.csv")
